ruleContent.content:
@js:
try{
var options={"headers":{"Referer":baseUrl}};
const jsonMatch = result.match(/<script[^>]*id="chapter-data"[^>]*>\s*({[\s\S]*?})\s*<\/script>/);
 if (!jsonMatch) throw new Error('未找到章节数据');
var chapter = JSON.parse(jsonMatch[1]);
chapter.imageUrls.map(a=>
'<img src="'+a+','+JSON.stringify(options)+'">').join("\n")
}catch(e){}

